#include "KS/SRC/stringx.h"

#pragma interface

typedef unsigned char uint8;
typedef unsigned int uint32;

class color32 {
public:
    union {
        struct {
            uint8 b;
            uint8 g;
            uint8 r;
            uint8 a;
        } c;
        uint32 i;
    };

    color32(uint32 value = 0) : i(value) {}
    color32(uint8 red, uint8 green, uint8 blue, uint8 alpha = 255)
    {
        c.b = blue;
        c.g = green;
        c.r = red;
        c.a = alpha;
    }
};

class Font {
public:
    enum HORIZJUST {
        HORIZJUST_LEFT,
        HORIZJUST_CENTER,
        HORIZJUST_RIGHT
    };
    enum VERTJUST {
        VERTJUST_TOP,
        VERTJUST_CENTER,
        VERTJUST_BOTTOM
    };
};

class TextString {
protected:
    Font *font;
    stringx text;
    float x;
    float y;
    int z;
    Font::HORIZJUST hJustify;
    Font::VERTJUST vJustify;
    bool even_number_spacing;
    int fade;
    float fade_alpha;
    float fade_timer;
    float scale;
    float button_scale;
    bool override_alpha;

public:
    bool checkTime;
    float time;
    bool no_color;
    color32 color;

    TextString(
        Font *font,
        stringx text,
        float x,
        float y,
        int z,
        float scale,
        Font::HORIZJUST horizontal,
        Font::VERTJUST vertical,
        color32 color)
    {
        cons(
            font, text, x, y, z, scale,
            horizontal, vertical, false, color);
    }

    virtual ~TextString() {}

protected:
    virtual void cons(
        Font *font,
        stringx text,
        float x,
        float y,
        int z,
        float scale,
        Font::HORIZJUST horizontal,
        Font::VERTJUST vertical,
        bool no_color,
        color32 color = color32(0, 0, 0, 255));
};

class IGOWidget {
protected:
    bool display;

public:
    IGOWidget();
    virtual ~IGOWidget();
    virtual void SetDisplay(bool enabled = true);
    virtual void Update(float time);
    virtual void Draw();
    virtual bool GetDisplay() const;
};

class PanelQuad;

class SplitClockWidget : public IGOWidget {
private:
    PanelQuad *bgPQ;
    TextString *timeText;
    float clockSec;
    int clockMin;

public:
    SplitClockWidget();
    virtual ~SplitClockWidget();
};

void *operator new(
    unsigned int size,
    unsigned int alignment,
    const char *description,
    int line);

